    "beschreibung": "Předmětem veřejné zakázky je zajištění odborných kapacit z oblasti informačních a komunikačních technologií (dále jen „ICT“), a to jednak pro interní potřeby Zadavatele a dále pro zadavatele, se kterými bude uzavřena smlouva o centralizovaném zadávání. Zadavatel předpokládá, že pověřujícími zadavateli budou zejména jím řízené organizace a případně partneři v rámci společných projektů, jimiž mohou být orgány státní správy a samosprávy a organizace v jejich přímé působnosti. Odborné kapacity, které budou předmětem veřejné zakázky a budou sloužit k vývoji, rozvoji a správě ICT systémů jsou zejména enterprise architekti, projektový manažer, specialista kybernetické bezpečnosti, SW vývojář, tester. Podrobnější informace jsou uvedeny v zadávací dokumentaci.",
