    "beschreibung": "V pripravi je državni prostorski načrt za Letališče Edvarda Rusjana Maribor (v nadaljnjem besedilu: DPN LJMB). Pobudnik in investitor DPN je Ministrstvo za infrastrukturo in energetiko. S sprejemom DPN bo zagotovljena celovita ureditev LJMB in rezerviran ustrezen prostor za nadaljnjo širitev in posodabljanje letališke in druge infrastrukture. Z DPN LJMB bodo določena območja za umeščanje nove letališke in spremljajoče infrastrukture, ki obsega urejanje manevrskih površin ter umeščanje drugih objektov in naprav. Za DPN LJMB so že pridobljene smernice nosilcev urejanja prostora, izdana odločba o celoviti presoji vplivov na okolje in sprejet Sklep o pripravi DPN.",
