    "frist": "",
    "link": "https://ted.europa.eu/de/notice/-/detail/689750-2026",
    "cpvCodes": [
      "71000000",
      "71241000"
    ],
    "beschreibung": "Předmětem veřejné zakázky je aktualizace generelu odvodnění města Brandýs n. Labem – Stará Boleslav na základě dokumentu „Analýza změn a potřeb aktualizace generelu odvodnění města Brandýs nad Labem–Stará Boleslav“ zpracovaného v dubnu 2026 společností STAVOKOMPLET spol. s r.o., jako provozovatelem vodovodu a kanalizace pro veřejnou potřebu, a to s důrazem na tyto klíčové okruhy: • vytvoření aktualizovaného moderního nástroje pro poznání chování systému odvodnění, efektivní provozování stokové sítě a zefektivnění vynaložených finančních prostředků do systému v rámci plánu obnovy a také plánu údržby a oprav stokové sítě, • identifikace hlavních problémů odvodnění města, • návrh koncepce odvodnění zastavitelného území s výhledem dle územního plánu a dále zastavěného území dosud neřešeného; včetně doporučení optimalizačních opatření, • zajištění technické, ekonomické a ekologické vyváženosti návrhu rekonstrukcí a nových investičních záměrů souvisejících s dalším rozvojem systému v rámci plánu investic města. Bližší technická specifikace metodiky, rozsahu, členění a způsobu zpracování předmětu plnění; vč. dostupných podkladů, je uvedena v dokumentu „Analýza změn a potřeb aktualizace generelu odvodnění města Brandýs nad Labem – Stará Boleslav“ a v jeho přílohách (situace č. 1 až situace č. 4.).",
