    "beschreibung": "In der Klinik Donaustadt (sowie der angrenzenden Pflege Donaustadt) erfolgt die Ver- bzw Entsorgung beider Häuser (mit Speisen, Apothekengüter, Wäsche, Sterilgüter usw) über ein automatisches Transportsystem (kurz \"ATS\"). Das ATS wurde im Jahr 1992 von der Ing. Sumetzberger GmbH errichtet und seither angepasst. Der Transport der Rollwagen (Container) erfolgt dabei durch automatische Unterflur-Schleppfahrzeuge (kurz \"Transcar\"). Gegenstand des gegenständlichen Vergabeverfahrens ist die Wartung, Reparatur und Instandsetzung der bestehenden Container für das ATS in der von der Stadt Wien – Wiener Gesundheitsverbund betriebenen Klinik Donaustadt sowie der angrenzenden Pflege Donaustadt.",
