    "reviewLabel": "pruefen",
    "reviewScore": 55,
    "reviewReason": "Methodische Beratung zu strategischer Planung und Veränderungsmanagement für Sozialorganisationen in Tschechien, Beratung, aber nicht raumbezogen.",
    "reviewProvider": "claude-automation",
    "reviewModel": "claude-sonnet-5-5",
